from itertools import combinations, permutations

# Kagome sites in doubled axial coordinates, over a box safely larger than any 5-site connected cluster.
sites=[]
for i in range(-4,5):
    for j in range(-4,5):
        sites += [(2*i,2*j),(2*i+1,2*j),(2*i,2*j+1)]
site_set=set(sites)

def neighbors(p):
    x,y=p
    # From unit-cell NN definitions above: undirected deltas.
    ds=[(1,0),(-1,0),(0,1),(0,-1),(-1,1),(1,-1)]
    return [(x+dx,y+dy) for dx,dy in ds if (x+dx,y+dy) in site_set]

def connected(S):
    seen={next(iter(S))}
    stack=list(seen)
    while stack:
        p=stack.pop()
        for q in neighbors(p):
            if q in S and q not in seen:
                seen.add(q); stack.append(q)
    return len(seen)==len(S)

def edges(S):
    E=[]
    for p in S:
        for q in neighbors(p):
            if q in S and p<q: E.append((p,q))
    return E

def canon_graph(S):
    pts=list(S); E=set(edges(S)); idx={p:k for k,p in enumerate(pts)}
    best=None
    for perm in permutations(range(5)):
        mapped=[]
        for a,b in E:
            u,v=idx[a],idx[b]
            ru,rv=perm[u],perm[v]
            mapped.append(tuple(sorted((ru,rv))))
        key=tuple(sorted(mapped))
        if best is None or key<best: best=key
    return best

classes={}
